contract InvMutTest {
    C c;
    bool rejectFlag;

    constructor(C _c) { c = _c; rejectFlag = false; }

    function run(uint amount, bool reject) public payable {
        require(true);
        rejectFlag = false;
        c.addToBalance{value: amount}();
        uint before = c.getBalance(address(this));
        rejectFlag = reject;
        bool reverted;
        try c.withdrawBalance() { reverted = false; }
        catch { reverted = true; }
        rejectFlag = false;
        assert((reject && reverted && c.getBalance(address(this)) == before) ||
               (!reject && !reverted && c.getBalance(address(this)) == 0));
    }

    receive() external payable {
        if (rejectFlag) { revert(); }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        c.addToBalance{value: amount}();
        uint tracked = c.getBalance(address(this));
        assert(tracked == amount);
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;
        c.withdrawBalance();
        assert(address(this).balance == beforeThis + tracked);
        assert(address(c).balance == beforeC - tracked);
        assert(c.getBalance(address(this)) == 0);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    bool public refuse;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        c.addToBalance{value: amount}();
        uint beforeBal = c.getBalance(address(this));
        uint contractEthBefore = address(c).balance;
        refuse = true;
        bool reverted;
        try c.withdrawBalance() { reverted = false; }
        catch { reverted = true; }
        refuse = false;
        uint afterBal = c.getBalance(address(this));
        uint contractEthAfter = address(c).balance;
        assert(reverted && afterBal == beforeBal && contractEthAfter == contractEthBefore);
    }
    receive() external payable { require(!refuse); }
}
